pattern.example_bad:

// VULNERABLE: Direct string concatenation
const query = "SELECT * FROM users WHERE id = " + userId;
db.execute(query);

pattern.example_good:

// SECURE: Parameterized queries
const query = "SELECT * FROM users WHERE id = ?";
db.execute(query, [userId]);

pattern.example_bad:

// VULNERABLE: Unescaped user input
const userHtml = "<div>" + userInput + "</div>";
element.innerHTML = userHtml;

pattern.example_good:

// SECURE: Proper escaping or sanitization
const userHtml = sanitizer.sanitize(userInput);
element.textContent = userInput; // or use textContent

pattern.example_bad:

// VULNERABLE: Hardcoded API key
const apiKey = "sk_live_1234567890abcdef";
const client = new StripeClient(apiKey);

pattern.example_good:

// SECURE: Environment variable
const apiKey = process.env.STRIPE_API_KEY;
const client = new StripeClient(apiKey);

pattern.example_bad:

// VULNERABLE: No auth check
app.get('/admin/users', (req, res) => {
  const users = db.getAllUsers();
  res.json(users);
});

pattern.example_good:

// SECURE: Authentication middleware
app.get('/admin/users', authenticateAdmin, (req, res) => {
  const users = db.getAllUsers();
  res.json(users);
});

pattern.example_bad:

// INEFFICIENT: N+1 query problem
const users = userIds.map(id => {
  return db.query('SELECT * FROM users WHERE id = ' + id);
});

pattern.example_good:

// EFFICIENT: Single query with IN clause
const users = db.query(
  'SELECT * FROM users WHERE id IN (?)',
  [userIds.join(',')]
);

pattern.example_bad:

// INEFFICIENT: No caching
function getUserProfile(userId) {
  return db.query('SELECT * FROM profiles WHERE user_id = ?', [userId]);
}

pattern.example_good:

// EFFICIENT: Cached results
const cache = new Map();
function getUserProfile(userId) {
  if (cache.has(userId)) {
    return cache.get(userId);
  }
  const profile = db.query('SELECT * FROM profiles WHERE user_id = ?', [userId]);
  cache.set(userId, profile);
  return profile;
}

pattern.example_bad:

// LEAK: Event listeners not removed
function setupButton() {
  button.addEventListener('click', handleClick);
}
// Button recreated but listener not removed

pattern.example_good:

// CLEAN: Proper cleanup
let clickHandler;
function setupButton() {
  clickHandler = handleClick;
  button.addEventListener('click', clickHandler);
}
function cleanupButton() {
  button.removeEventListener('click', clickHandler);
}

pattern.example_bad:

// UNCLEAR: Magic numbers
function calculateDiscount(price) {
  if (price > 100) {
    return price * 0.9;
  }
  return price * 0.95;
}

pattern.example_good:

// CLEAR: Named constants
const DISCOUNT_THRESHOLD = 100;
const HIGH_DISCOUNT_RATE = 0.9;
const STANDARD_DISCOUNT_RATE = 0.95;

function calculateDiscount(price) {
  if (price > DISCOUNT_THRESHOLD) {
    return price * HIGH_DISCOUNT_RATE;
  }
  return price * STANDARD_DISCOUNT_RATE;
}

pattern.example_bad:

// DUPLICATED: Same validation logic repeated
function validateEmail(email) {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(email);
}

function validateUserEmail(userEmail) {
  const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return regex.test(userEmail);
}

pattern.example_good:

// DRY: Single validation function
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function validateEmail(email) {
  return EMAIL_REGEX.test(email);
}

function validateUserEmail(userEmail) {
  return validateEmail(userEmail);
}

pattern.example_bad:

// HARD TO READ: Deep nesting
function processUsers(users) {
  users.forEach(user => {
    if (user.active) {
      user.roles.forEach(role => {
        if (role.permissions) {
          role.permissions.forEach(perm => {
            if (perm.granted) {
              console.log(perm.name);
            }
          });
        }
      });
    }
  });
}

pattern.example_good:

// READABLE: Early returns and flat structure
function processUsers(users) {
  return users
    .filter(user => user.active)
    .flatMap(user => user.roles)
    .filter(role => role.permissions)
    .flatMap(role => role.permissions)
    .filter(perm => perm.granted)
    .map(perm => perm.name);
}

pattern.example_bad:

// INCONSISTENT: Mixed error handling
function getData() {
  try {
    return fetch(url);
  } catch (e) {
    console.error(e); // Sometimes logged
    throw e; // Sometimes thrown
  }
}

function saveData(data) {
  try {
    return db.save(data);
  } catch (e) {
    return null; // Sometimes returns null
  }
}

pattern.example_good:

// CONSISTENT: Unified error handling
class AppError extends Error {
  constructor(message, code) {
    super(message);
    this.code = code;
  }
}

function getData() {
  try {
    return fetch(url);
  } catch (e) {
    throw new AppError('Failed to fetch data', 'FETCH_ERROR');
  }
}

function saveData(data) {
  try {
    return db.save(data);
  } catch (e) {
    throw new AppError('Failed to save data', 'SAVE_ERROR');
  }
}

pattern.example_bad:

// INCOMPLETE: Only happy path tested
test('calculates discount', () => {
  expect(calculateDiscount(150)).toBe(135);
});

pattern.example_good:

// COMPLETE: Edge cases covered
describe('calculateDiscount', () => {
  test('applies high discount for prices above threshold', () => {
    expect(calculateDiscount(150)).toBe(135);
  });

  test('applies standard discount for prices at threshold', () => {
    expect(calculateDiscount(100)).toBe(95);
  });

  test('applies standard discount for prices below threshold', () => {
    expect(calculateDiscount(99)).toBe(94.05);
  });

  test('handles zero price', () => {
    expect(calculateDiscount(0)).toBe(0);
  });

  test('handles negative price', () => {
    expect(calculateDiscount(-10)).toBe(-9.5);
  });
});

pattern.example_bad:

// FRAGILE: Tests implementation details
test('sets user status to active', () => {
  const user = new User();
  user.setStatus('active');
  expect(user.status).toBe('active');
  expect(user._statusHistory).toEqual(['active']); // Implementation detail
});

pattern.example_good:

// ROBUST: Tests observable behavior
test('user status is reflected in isActive', () => {
  const user = new User();
  user.setStatus('active');
  expect(user.isActive()).toBe(true); // Tests public interface
});

pattern.example_bad:

// INCOMPLETE: Only success cases tested
test('fetches user data', async () => {
  const data = await fetchUser(123);
  expect(data.id).toBe(123);
});

pattern.example_good:

// COMPLETE: Error cases tested
describe('fetchUser', () => {
  test('fetches user data successfully', async () => {
    const data = await fetchUser(123);
    expect(data.id).toBe(123);
  });

  test('handles user not found error', async () => {
    await expect(fetchUser(999)).rejects.toThrow('User not found');
  });

  test('handles network errors', async () => {
    await expect(fetchUser(123)).rejects.toThrow('Network error');
  });
});
